 "content": "def transform(grid):
    """Extend diagonal same-color pairs outward through background cells."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = max(set(v for row in grid for v in row),
                     key=lambda v: sum(row.count(v) for row in grid))
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= cc < w) or grid[rr][cc] != color:
                    continue
                for ar, ac, sr, sc in ((r, c, -dr, -dc), (rr, cc, dr, dc)):
                    nr, nc = ar + sr, ac + sc
                    while 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background:
                        out[nr][nc] = color
                        nr += sr
                        nc += sc
    return out
